create table if not exists public.team_data_retention_settings (
team_id uuid primary key references public.teams(id) on delete cascade,
daily_evolution_days int not null default 90 check(daily_evolution_days between 30 and 730),
tournament_days int not null default 30 check(tournament_days between 7 and 365),
completed_task_days int not null default 90 check(completed_task_days between 30 and 730),
completed_training_days int not null default 90 check(completed_training_days between 30 and 730),
updated_at timestamptz not null default now());
alter table public.team_data_retention_settings enable row level security;
revoke all on public.team_data_retention_settings from anon,authenticated;
grant select,insert,update on public.team_data_retention_settings to authenticated;
drop policy if exists team_retention_member_read on public.team_data_retention_settings;
create policy team_retention_member_read on public.team_data_retention_settings for select to authenticated using(exists(select 1 from public.team_members tm where tm.team_id=team_data_retention_settings.team_id and tm.user_id=auth.uid() and tm.status='active'));
drop policy if exists team_retention_owner_insert on public.team_data_retention_settings;
create policy team_retention_owner_insert on public.team_data_retention_settings for insert to authenticated with check(exists(select 1 from public.team_members tm where tm.team_id=team_data_retention_settings.team_id and tm.user_id=auth.uid() and tm.status='active' and tm.membership_role='owner'));
drop policy if exists team_retention_owner_update on public.team_data_retention_settings;
create policy team_retention_owner_update on public.team_data_retention_settings for update to authenticated using(exists(select 1 from public.team_members tm where tm.team_id=team_data_retention_settings.team_id and tm.user_id=auth.uid() and tm.status='active' and tm.membership_role='owner')) with check(exists(select 1 from public.team_members tm where tm.team_id=team_data_retention_settings.team_id and tm.user_id=auth.uid() and tm.status='active' and tm.membership_role='owner'));
insert into public.team_data_retention_settings(team_id,daily_evolution_days,tournament_days,completed_task_days,completed_training_days) select t.id,c.daily_evolution_days,c.tournament_days,c.completed_task_days,c.completed_training_days from public.teams t cross join public.data_retention_settings c where c.id=true on conflict(team_id) do nothing;
create or replace function public.run_squad_os_retention_cleanup() returns jsonb language plpgsql security definer set search_path=public as $$ declare cfg record; ds bigint:=0;tc bigint:=0;pt bigint:=0;ts bigint:=0;tl bigint:=0;n bigint; begin for cfg in select t.id team_id,coalesce(r.daily_evolution_days,g.daily_evolution_days,90) daily_days,coalesce(r.tournament_days,g.tournament_days,30) tournament_days,coalesce(r.completed_task_days,g.completed_task_days,90) task_days,coalesce(r.completed_training_days,g.completed_training_days,90) training_days from public.teams t left join public.team_data_retention_settings r on r.team_id=t.id left join public.data_retention_settings g on g.id=true loop delete from public.daily_scores where team_id=cfg.team_id and score_date<((now() at time zone 'Asia/Kolkata')::date-cfg.daily_days);get diagnostics n=row_count;ds:=ds+n;delete from public.tournament_cycles where team_id=cfg.team_id and cycle_end<((now() at time zone 'Asia/Kolkata')::date-cfg.tournament_days) and status in ('completed','cancelled','archived');get diagnostics n=row_count;tc:=tc+n;delete from public.practice_tasks where team_id=cfg.team_id and status in ('completed','reviewed','cancelled') and coalesce(reviewed_at,completed_at,updated_at)<now()-make_interval(days=>cfg.task_days);get diagnostics n=row_count;pt:=pt+n;delete from public.training_sessions where team_id=cfg.team_id and status='completed' and completed_at<now()-make_interval(days=>cfg.training_days);get diagnostics n=row_count;ts:=ts+n;delete from public.training_log where team_id=cfg.team_id and created_at<now()-interval '180 days';get diagnostics n=row_count;tl:=tl+n;end loop;return jsonb_build_object('daily_scores_deleted',ds,'tournaments_deleted',tc,'tasks_deleted',pt,'sessions_deleted',ts,'training_logs_deleted',tl,'ran_at',now());end;$$;
revoke all on function public.run_squad_os_retention_cleanup() from public,anon,authenticated;